/// ```text
/// 3.2.9 Object: Native
///
/// This object represents a native type impression.
/// Native ad units are intended to blend seamlessly into the surrounding content (e.g., a sponsored
/// Twitter or Facebook post).
/// As such, the response must be well-structured to afford the publisher fine-grained control over
/// rendering.
///
/// The Native Subcommittee has developed a companion specification to OpenRTB called the Dynamic
/// Native Ads API.
/// It defines the request parameters and response markup structure of native ad units.
/// This object provides the means of transporting request parameters as an opaque string so that
/// the specific parameters can evolve separately under the auspices of the Dynamic Native Ads API.
/// Similarly, the ad markup served will be structured according to that specification.
///
/// The presence of a Native as a subordinate of the Imp object indicates that this impression is
/// offered as a native type impression.
/// At the publisher’s discretion, that same impression may also be offered as banner, video, and/or
/// audio by also including as Imp subordinates objects of those types.
/// However, any given bid for the impression must conform to one of the offered types.
/// ```
#[derive(Clone, Debug, Default, PartialEq, Eq, GoJson)]
#[gojson(go_type = "openrtb2.Native")]
pub struct Native {
    /// ```text
    /// Attribute:
    ///   request
    /// Type:
    ///   string; required
    /// Description:
    ///   Request payload complying with the Native Ad Specification.
    ///   The root node of the payload, “native”, was dropped in the
    ///   Native Ad Specification 1.1.
    ///
    ///   For Native 1.0, this is a JSON-encoded string consisting of a
    ///   unnamed root object with a single subordinate object named
    ///   'native', which is the Native Markup Request object, section 4.1
    ///   of OpenRTB Native 1.0 specification.
    ///
    ///   For Native 1.1 and higher, this is a JSON-encoded string
    ///   consisting of an unnamed root object which is itself the Native
    ///   Markup Request Object, section 4.1 of OpenRTB Native 1.1+.
    /// ```
    #[gojson(go = "Request", json = "request")]
    pub request: String,
    /// ```text
    /// Attribute:
    ///   ver
    /// Type:
    ///   string; recommended
    /// Description:
    ///   Version of the Dynamic Native Ads API to which request
    ///   complies; highly recommended for efficient parsing.
    /// ```
    #[gojson(go = "Ver", json = "ver,omitempty")]
    pub ver: String,
    /// ```text
    /// Attribute:
    ///   api
    /// Type:
    ///   integer array
    /// Description:
    ///   List of supported API frameworks for this impression. Refer to
    ///   List: API Frameworks in AdCOM. If an API is not explicitly listed,
    ///   it is assumed not to be supported.
    /// Note:
    ///   OpenRTB <=2.5 defined only frameworks 1..6.
    /// ```
    #[gojson(go = "API", json = "api,omitempty")]
    pub api: Option<Vec<adcom1::APIFramework>>,
    /// ```text
    /// Attribute:
    ///   sequence
    /// Type:
    ///   integer array
    /// Description:
    ///   Blocked creative attributes. Refer to List: Creative Attributes in
    ///   AdCOM.
    /// Note:
    ///   OpenRTB <=2.5 defined only attributes with IDs 1..17.
    /// ```
    #[gojson(go = "BAttr", json = "battr,omitempty")]
    pub battr: Option<Vec<adcom1::CreativeAttribute>>,
    /// ```text
    /// Attribute:
    ///   ext
    /// Type:
    ///   object
    /// Description:
    ///   Placeholder for exchange-specific extensions to OpenRTB.
    /// ```
    #[gojson(go = "Ext", json = "ext,omitempty")]
    pub ext: RawJson,
}

